; prices.asm -- appendix I: the instructions the answers price, each between two labels
; generated by genI.py
        INCLUDE "msx.inc"
        OUTPUT "prices.rom"
        ORG $4000
        CART_HEADER init
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off, no frame interrupt
        in a, (VDP_CTRL)        ; and none waiting
        VRAM_WRITE $0000        ; the bytes OUTI and OTIR send go to the VRAM
; nop
p_nop: nop
q_nop: nop
; ld_a_n
p_ld_a_n: ld a, 7
q_ld_a_n: nop
; ld_b_n
p_ld_b_n: ld b, 7
q_ld_b_n: nop
; ld_c_n
p_ld_c_n: ld c, 7
q_ld_c_n: nop
; ld_de_nn
p_ld_de_nn: ld de, $1234
q_ld_de_nn: nop
; xor_d
p_xor_d: xor d
q_xor_d: nop
; inc_hl
p_inc_hl: inc hl
q_inc_hl: nop
; exx
p_exx: exx
q_exx: exx
; di
p_di: di
q_di: nop
; ei
p_ei: ei
q_ei: di
; ld_a_mem
p_ld_a_mem: ld a, (RAM_START)
q_ld_a_mem: nop
; ld_hl_mem
p_ld_hl_mem: ld hl, (RAM_START)
q_ld_hl_mem: nop
; ld_mem_hl
p_ld_mem_hl: ld (RAM_START), hl
q_ld_mem_hl: nop
; push_hl
p_push_hl: push hl
q_push_hl: pop hl
; pop_hl
        push hl
p_pop_hl: pop hl
q_pop_hl: nop
; ld_a_ix5
        ld ix, RAM_START
p_ld_a_ix5: ld a, (ix+5)
q_ld_a_ix5: nop
; set_1_ix2
        ld ix, RAM_START
p_set_1_ix2: set 1, (ix+2)
q_set_1_ix2: nop
; out_n_a
        xor a
p_out_n_a: out (VDP_DATA), a
q_out_n_a: nop
; out_c_a
        ld c, VDP_DATA
p_out_c_a: out (c), a
q_out_c_a: nop
; jp_nn
p_jp_nn: jp q_jp_nn
q_jp_nn: nop
; jp_nz_taken
        or 1
p_jp_nz_taken: jp nz, q_jp_nz_taken
q_jp_nz_taken: nop
; jp_nz_not
        xor a
p_jp_nz_not: jp nz, p_jp_nz_not
q_jp_nz_not: nop
; jr_taken
p_jr_taken: jr q_jr_taken
q_jr_taken: nop
; jr_nz_not
        xor a
p_jr_nz_not: jr nz, p_jr_nz_not
q_jr_nz_not: nop
; djnz_taken
        ld b, 2
p_djnz_taken: djnz q_djnz_taken
q_djnz_taken: nop
; djnz_not
        ld b, 1
p_djnz_not: djnz p_djnz_not
q_djnz_not: nop
; ret
        ld hl, q_ret
        push hl
p_ret: ret
q_ret: nop
; ldi
        ld hl, $4000
        ld de, RAM_START
        ld bc, 1
p_ldi: ldi
q_ldi: nop
; ldir_1
        ld hl, $4000
        ld de, RAM_START
        ld bc, 1
p_ldir_1: ldir
q_ldir_1: nop
; ldir_2
        ld hl, $4000
        ld de, RAM_START
        ld bc, 2
p_ldir_2: ldir
q_ldir_2: nop
; ldir_256
        ld hl, $4000
        ld de, RAM_START
        ld bc, 256
p_ldir_256: ldir
q_ldir_256: nop
; outi
        ld hl, $4000
        ld c, VDP_DATA
        ld b, 1
p_outi: outi
q_outi: nop
; otir_1
        ld hl, $4000
        ld c, VDP_DATA
        ld b, 1
p_otir_1: otir
q_otir_1: nop
; otir_2
        ld hl, $4000
        ld c, VDP_DATA
        ld b, 2
p_otir_2: otir
q_otir_2: nop
; otir_128
        ld hl, $4000
        ld c, VDP_DATA
        ld b, 128
p_otir_128: otir
q_otir_128: nop
; otir_256
        ld hl, $4000
        ld c, VDP_DATA
        ld b, 0
p_otir_256: otir
q_otir_256: nop
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
